def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay settings on the defaults mode="fast" and level="3".

    keys[i] is set to values[i]. The result lists the value of "mode",
    then the value of "level", then the value of each other distinct key
    in order of first appearance in keys. A repeated key takes its last
    value. Only the first len(keys) entries of values are used when the
    lengths differ, and a missing value is treated as "".
    """
    overrides: dict[str, str] = {}
    for i, key in enumerate(keys):
        overrides[key] = values[i] if i < len(values) else ""
    result: list[str] = [overrides.get("mode", "fast"), overrides.get("level", "3")]
    for key, value in overrides.items():
        if key not in ("mode", "level"):
            result.append(value)
    return result


def test_defaults_when_no_overrides() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode_and_level() -> None:
    assert settings(["mode", "level"], ["slow", "5"]) == ["slow", "5"]


def test_partial_override_keeps_other_default() -> None:
    assert settings(["level"], ["7"]) == ["fast", "7"]
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_extra_keys_follow_defaults() -> None:
    assert settings(["color"], ["red"]) == ["fast", "3", "red"]


def test_extra_keys_keep_input_order() -> None:
    assert settings(["z", "a"], ["1", "2"]) == ["fast", "3", "1", "2"]


def test_duplicate_key_last_value_wins() -> None:
    assert settings(["x", "x"], ["1", "2"]) == ["fast", "3", "2"]
